define("block_exaport/item_blocks",["jquery","jqueryui","core/modal_save_cancel"],function($,JQueryUI,ModalSaveCancel){var config={},updateOrderField=function(){var ids=[];$(".exaport-item-block-list [data-blockid]").each(function(){ids.push(parseInt($(this).attr("data-blockid"),10))}),$("#id_blockorder").val(JSON.stringify(ids))},showChooser=function(){if(!config.hasitem)return void window.alert(config.strings.savefirst);var body='<div class="list-group"><a class="list-group-item list-group-item-action" href="'+config.chooserurl+'&blockaction=add&blocktype=text">'+config.strings.text+'</a><a class="list-group-item list-group-item-action" href="'+config.chooserurl+'&blockaction=add&blocktype=file">'+config.strings.file+'</a><a class="list-group-item list-group-item-action" href="'+config.chooserurl+'&blockaction=add&blocktype=link">'+config.strings.link+"</a></div>";ModalSaveCancel.create({title:config.strings.choosertitle,body:body}).then(function(modal){return modal.getFooter().hide(),modal.show(),modal})},initSortable=function(){$(".exaport-item-block-list").length&&($(".exaport-item-block-list").sortable({handle:".exaport-item-block-handle",placeholder:"block-placeholder",forcePlaceholderSize:!0,update:updateOrderField}),updateOrderField())};return{init:function(initconfig){config=initconfig||{},$("body").on("click",".exaport-add-content",function(e){e.preventDefault(),showChooser()}),initSortable()}}});
